/-- A bounded regime whose predecessor sets use exactly the ordering selected by the
law-only population decoder. -/
abbrev DecoderSelectedBoundedRegime {n : ℕ} {G : Causalean.DAG (Fin n)}
    {θ : Mechanism n G} (W : ModelGeneratedObservedWorld G θ) :=
  {R : BoundedRegime W.1 //
    R.order = selectedTopologicalOrder (observedProbabilityLawFamily W.1.law)}

/-- A numerical linear extension of a directed relation. Injectivity excludes tied labels. -/
def IsTopologicalOrdering (E : Fin n → Fin n → Prop) (order : Fin n → ℕ) : Prop :=
  Function.Injective order ∧ ∀ ⦃j i⦄, E j i → order j < order i

/-- A decoder input consists of genuine probability laws in all `n+1` environments. -/
abbrev ObservedProbabilityLawFamily (n : ℕ) :=
  {laws : ObservedLawFamily n // ∀ e, IsProbabilityMeasure (laws e)}

/-- The degree-one polynomial whose value at `t` is the affine interpolation from `a` to `b`. -/
def affineFactorPolynomial (a b : ℝ) : Polynomial ℝ :=
  Polynomial.C a + Polynomial.X * Polynomial.C (b - a)

/-- An edge-free DAG has no ancestral covers.  Given [the stated inputs and conditions](hyp:hG,hji), [the stated conclusion](goal) follows. -/
lemma ancestralCover_false_of_no_edge
    {n : ℕ} {G : Causalean.DAG (Fin n)}
    (hG : ∀ j i, ¬ G.edge j i) {j i : Fin n}
    (hji : ancestralCover G j i) : False := by
  exact hG j i (ancestralCover_edge hji)

/-- The cancellation primitive `H`. -/
def cancellationPrimitive (x : ℝ) : ℝ :=
  (Real.exp (4 * x) - 1) / (Real.exp 4 - 1) - x

