/-- The normalized exponential intervention density. -/
def exponentialInterventionDensity (z : ℝ) : ℝ :=
  4 * Real.exp (4 * z) / (Real.exp 4 - 1)

/-- Projection of a coordinate family onto a finite index set. -/
def familyProjection {X Y : Type*} (U : Fin n → X → Y) (S : Finset (Fin n))
    (x : X) : (j : {j // j ∈ S}) → Y := fun j => U j x

/-- The explicit Gaussian feature vector in real `ℓ²`. -/
def gaussianFeature (r : ℝ) : lp (fun _ : ℕ => ℝ) 2 :=
  ⟨gaussianFeatureCoefficient r, gaussianFeature_memℓp r⟩

/-- The `m`th coordinate of the paper's explicit Gaussian feature expansion. -/
def gaussianFeatureCoefficient (r : ℝ) (m : ℕ) : ℝ :=
  Real.sqrt ((2 : ℝ) ^ m / m.factorial) * Real.exp (-r ^ 2) * r ^ m

/-- The Gaussian kernel `exp (-(a-b)²)`. -/
def gaussianKernel (a b : ℝ) : ℝ :=
  Real.exp (-(a - b) ^ 2) -- @realizes k(exp (-(a-b)^2), range (0,1])

/-- The closed latent cube. -/
def latentCube (n : ℕ) : Set (LatentState n) :=
  Set.pi Set.univ (fun _ => Set.Icc (0 : ℝ) 1) -- @realizes V(range [0,1]^n)

/-- The observable log-ratio coordinate. -/
def logRatio (W : ObservedWorld G θ) (i : Fin n) (x : LatentState n) : ℝ :=
  Real.log (W.ratio i x) -- @realizes \(L_i\)(log R_i)

/-- Maximum conditioning dimension of the selected ordering. -/
def maximumConditioningDimension : ℕ :=
  Finset.univ.sup (fun i : Fin n => (predecessorSet R.order i).card)

